package net.civeira.phylax.feature.template.theme.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.template.theme.domain.Theme;
import net.civeira.phylax.feature.template.theme.domain.valueobject.IsDefaultVO;

class IsDefaultValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of is default of theme")
  void test_is_default_value_holder_assign_plain_value() {
    Object holder = new Object();
    IsDefaultValueHolder<Object> value = new IsDefaultValueHolder<>(holder);
    Assertions.assertSame(holder, value.isDefault(true), "Setters must return the holder");
    Assertions.assertTrue(value.getIsDefaultValue().isPresent(), "The plain value must be stored");
    Assertions.assertEquals(true, value.getIsDefault().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.isDefaultNull(), "Setters must return the holder");
    Assertions.assertTrue(value.getIsDefaultValue().isPresent(),
        "A null value object must be stored");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of is default of theme")
  void test_is_default_value_holder_assign_value_object() {
    Object holder = new Object();
    IsDefaultValueHolder<Object> value = new IsDefaultValueHolder<>(holder);
    IsDefaultVO vo = IsDefaultVO.from(true);
    Assertions.assertFalse(value.getIsDefaultValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.isDefault(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getIsDefaultValue().orElseThrow());
    Assertions.assertSame(holder, value.isDefault(Optional.empty()));
    Assertions.assertFalse(value.getIsDefaultValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.isDefault(Optional.of(vo)));
    Assertions.assertSame(vo, value.getIsDefaultValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of is default of theme against the original")
  void test_is_default_value_holder_read() {
    Object holder = new Object();
    IsDefaultValueHolder<Object> value = new IsDefaultValueHolder<>(holder);
    IsDefaultVO vo = IsDefaultVO.from(true);
    IsDefaultVO other = IsDefaultVO.from(true);
    Theme original = Mockito.mock(Theme.class);
    Mockito.when(original.getIsDefaultValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readIsDefault(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readIsDefault(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.isDefault(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readIsDefault(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readIsDefault(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of is default of theme")
  void test_is_default_value_holder_unset() {
    Object holder = new Object();
    IsDefaultValueHolder<Object> value = new IsDefaultValueHolder<>(holder);
    IsDefaultVO vo = IsDefaultVO.from(true);
    value.isDefault(vo);
    Assertions.assertSame(holder, value.unsetIsDefaultIfMatches("isDefault_other"));
    Assertions.assertTrue(value.getIsDefaultValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetIsDefaultIfMatches("isDefault"));
    Assertions.assertFalse(value.getIsDefaultValue().isPresent(),
        "The field name must clear the value");
    value.isDefault(vo);
    Assertions.assertSame(holder, value.unsetIsDefault());
    Assertions.assertFalse(value.getIsDefaultValue().isPresent(), "Unset must clear the value");
  }
}
